export const tests: Tests = {
	"an expired session writes an audit entry and returns expired": () => {
		const session = makeSession({ expiresAt: T0 + HOUR });
		const store = createMemorySessionStore([session]);
		const later = fixedClock(T0 + HOUR + MINUTE);
		const audit = createAuditLog();
		const response = handleLogin(session.id, { store, audit, now: later });
		assert.eq(response.status, 419); // or expired status code
		assert.deepEq(response.body, { error: "expired" });
		assert.deepEq(lastEntry(audit), { event: "session.expired", at: T0 + HOUR + MINUTE, subject: session.userId });
		assert.eq(entriesFor(audit, "session.expired").length, 1);
	},
	"a missing or unknown session writes no expired entry": () => {
		const store = createMemorySessionStore();
		const audit = createAuditLog();
		const res1 = handleLogin(undefined, { store, audit, now: fixedClock(T0) });
		assert.eq(res1.status, 401);
		const res2 = handleLogin("unknown_token", { store, audit, now: fixedClock(T0) });
		assert.eq(res2.status, 401);
		assert.eq(entriesFor(audit, "session.expired").length, 0);
	},
	"a valid session writes no expired entry": () => {
		const session = makeSession({ expiresAt: T0 + HOUR });
		const store = createMemorySessionStore([session]);
		const audit = createAuditLog();
		const response = handleLogin(session.id, { store, audit, now: fixedClock(T0 + 30 * MINUTE) });
		assert.eq(response.status, 200);
		assert.eq(entriesFor(audit, "session.expired").length, 0);
	},
};

